{"name": "create_orange_image_page", "type": "sequential", "steps": [
  {"tool": "file_write",
   "args": {
     "path": "$profile.workspace/orange.html",
     "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Orange Image</title>
  <style>
    body {
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      background-color: #fff8f0;
      margin: 0;
      font-family: Arial, sans-serif;
    }
    img {
      border-radius: 8px;
      box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
      max-width: 90%;
      height: auto;
    }
  </style>
</head>
<body>
  <img src="https://upload.wikimedia.org/wikipedia/commons/c/c4/Orange-Fruit-Pieces.jpg" alt="An orange fruit">
</body>
</html>"
   },
   "store_result_as": "$write",
   "description": "Create an HTML page showing an image of an orange."},
  {"tool": "app_open",
   "args": {"target": "$profile.workspace/orange.html"},
   "description": "Open the orange image page for the user to view."}
]}

